beforeExample:
public class MyClass {
    public String getStringReference(String input) {
        return new java.lang.String(input);
    }
    public String getLiteral() {
        return new java.lang.String("Hello");
    }
    public String getEmptyString() {
        return new java.lang.String("");
    }
    public String methodCallInput() {
        return new java.lang.String(getStringReference("test"));
    }
    public String nonStringInput() {
        char[] chars = {'a', 'b', 'c'};
        return new java.lang.String(chars); // Should not match
    }
}

afterExample:
public class MyClass {
    public String getStringReference(String input) {
        return input;
    }
    public String getLiteral() {
        return "Hello";
    }
    public String getEmptyString() {
        return "";
    }
    public String methodCallInput() {
        return getStringReference("test");
    }
    public String nonStringInput() {
        char[] chars = {'a', 'b', 'c'};
        return new java.lang.String(chars); // Still new String(chars)
    }
}

negativeExample:
public class MyOtherClass {
    public String fromChars() {
        char[] data = {'x', 'y', 'z'};
        // This must NOT match because 'data' is char[], not String.
        return new java.lang.String(data);
    }
    public String fromBytes() {
        byte[] data = {1, 2, 3};
        // This must NOT match because 'data' is byte[], not String.
        return new java.lang.String(data);
    }
    public String fromBytesWithCharset(byte[] bytes) {
        // This must NOT match because 'bytes' is byte[] and a charset is involved.
        return new java.lang.String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    }
}
